import itertools

def max_overlap_disjoint_with_n1n2(m, p):
    min_n1_plus_n2 = float('inf')
    for p_seq in itertools.combinations(range(2*m + 2*p), 2*m):
        a_indices = list(p_seq)
        b_indices = [i for i in range(2*m + 2*p) if i not in p_seq]
        n1 = 0
        for i in range(1, m + 1):
            y_i_pos = a_indices[2*i - 1]
            for j in range(1, p + 1):
                x_prime_j_pos = b_indices[2*j - 2]
                if y_i_pos < x_prime_j_pos:
                    n1 += 1
        n2 = 0
        for j in range(1, p + 1):
            y_prime_j_pos = b_indices[2*j - 1]
            for i in range(1, m + 1):
                x_i_pos = a_indices[2*i - 2]
                if y_prime_j_pos < x_i_pos:
                    n2 += 1
        min_n1_plus_n2 = min(min_n1_plus_n2, n1 + n2)
    return m*p - min_n1_plus_n2

for m in range(1, 6):
